import java.util.*;
public class Ledger {
 private final Map<String,Integer> requests=new HashMap<>(); private int balance;
 public synchronized int credit(String key,int amount){
  if(requests.containsKey(key)){if(requests.get(key)!=amount)throw new IllegalArgumentException(); return balance;}
  balance+=amount; requests.put(key,amount); return balance;
 }
 public synchronized int balance(){return balance;}
}

