import java.util.*;
import java.math.*;
public class BehaviorCheck {
  public static void main(String[] args) throws Exception {
    var ledger = new Ledger(); ledger.credit("a",10); ledger.credit("a",10); assert ledger.balance()==10;
    try { ledger.credit("a",20); throw new AssertionError(); } catch(IllegalArgumentException expected){}
    assert ledger.balance()==10;
    var threads=new ArrayList<Thread>(); for(int i=0;i<12;i++){var t=new Thread(()->ledger.credit("b",7));threads.add(t);t.start();} for(var t:threads)t.join(); assert ledger.balance()==17;
    System.out.println("BehaviorCheck: PASS");
  }
}

